mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Party_B_Id as conPartyBId, con.Con_Project_Id as pId, c1.C_Name as ecSupervisorName, c2.C_Name as ecConsultingUnitName, d1.D_Name as ecDepName, c5.C_Name as ecCreateCName, c6.C_Name as conPartyBName, c7.C_Name as ecDesignName, c8.C_Name as ecPutForwardName, c9.C_Name as ecConstName, c10.C_Name as ecCostConsulName, c1.C_Abbreviation as ecSupervisorAbbName, c2.C_Abbreviation as ecConsultingUnitAbbName, c5.C_Abbreviation as ecCreateCAbbName, c6.C_Abbreviation as conPartyBAbbName, c7.C_Abbreviation as ecDesignAbbName, cl.Cl_Title as clTitle, sec.Sec_Name as secName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Major as dcoMajor, enis.Enis_Code as enisCode, ces.Enis_Project_Name as enisName, ces.Enis_Code as enisCodeSelf, pro1.P_Id as projectId, pro1.P_Name as projectName, pro1.P_Code as projectCode, pec.Ec_Name as preEcName, pec.Ec_Code as preEcCode, mn.* from Con_EC mn left join Pre_Project pro1 on mn.P_ID=pro1.P_ID left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Ec_Supervisor_Id=c1.C_Id left join SYS_Company c2 on mn.Ec_Consulting_Unit_Id=c2.C_Id left join Con_Contact_List cl on cl.Cl_Id=mn.Cl_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID
left join SYS_Department d1 on mn.Ec_Dep=d1.D_Id left join SYS_Company c5 on mn.Ec_Create_C_Id=c5.C_Id left join SYS_Company c6 on con.Con_Party_B_Id=c6.C_Id left join SYS_Company c7 on mn.Ec_Design_Id=c7.C_Id left join SYS_Company c8 on mn.Ec_Put_Forward=c8.C_Id left join SYS_Company c9 on mn.Ec_Construction=c9.C_Id left join SYS_Company c10 on mn.Ec_Cost_Consulting=c10.C_Id left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id left join Con_Enis enis on dco.Enis_Id=enis.Enis_Id left join Con_Enis ces on ces.Enis_Id=mn.Enis_Id left join Con_EC pec on pec.Ec_Id=mn.Pre_Ec_Id
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ec_Create_Time desc

select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Party_B_Id as conPartyBId, con.Con_Project_Id as pId, c1.C_Name as ecSupervisorName, c2.C_Name as ecConsultingUnitName, d1.D_Name as ecDepName, c5.C_Name as ecCreateCName, c6.C_Name as conPartyBName, c7.C_Name as ecDesignName, c8.C_Name as ecPutForwardName, c9.C_Name as ecConstName, c10.C_Name as ecCostConsulName, c1.C_Abbreviation as ecSupervisorAbbName, c2.C_Abbreviation as ecConsultingUnitAbbName, c5.C_Abbreviation as ecCreateCAbbName, c6.C_Abbreviation as conPartyBAbbName, c7.C_Abbreviation as ecDesignAbbName, cl.Cl_Title as clTitle, sec.Sec_Name as secName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Major as dcoMajor, enis.Enis_Code as enisCode, ces.Enis_Project_Name as enisName, ces.Enis_Code as enisCodeSelf, pro1.P_Id as projectId, pro1.P_Name as projectName, pro1.P_Code as projectCode, pec.Ec_Name as preEcName, pec.Ec_Code as preEcCode, con.con_declare_money conDeclareMoney, mn.* from Con_EC mn left join Pre_Project pro1 on mn.P_ID=pro1.P_ID left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Ec_Supervisor_Id=c1.C_Id left join SYS_Company c2 on mn.Ec_Consulting_Unit_Id=c2.C_Id left join Con_Contact_List cl on cl.Cl_Id=mn.Cl_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID
left join SYS_Department d1 on mn.Ec_Dep=d1.D_Id left join SYS_Company c5 on mn.Ec_Create_C_Id=c5.C_Id left join SYS_Company c6 on con.Con_Party_B_Id=c6.C_Id left join SYS_Company c7 on mn.Ec_Design_Id=c7.C_Id left join SYS_Company c8 on mn.Ec_Put_Forward=c8.C_Id left join SYS_Company c9 on mn.Ec_Construction=c9.C_Id left join SYS_Company c10 on mn.Ec_Cost_Consulting=c10.C_Id left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id left join Con_Enis enis on dco.Enis_Id=enis.Enis_Id left join Con_Enis ces on ces.Enis_Id=mn.Enis_Id left join Con_EC pec on pec.Ec_Id=mn.Pre_Ec_Id
${params.authSql}
where 1=1
and mn.multi_contract_con_ec_id = #{params.multiContractConEcId}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ec_Create_Time desc

select history.* from ( select ce.Ec_Id as ecId, ce.Con_Id as conId, mcce.uuid as flowId, mcce.change_code as changeCode, '01' as ecChangeType, ce.Ec_Apply_Money as ecApplyMoney, ce.Ec_Apply_Money_Type as ecApplyMoneyType, mcce.state as ecState, mcce.state_time as ecStateTime, ce.Ec_Total_Money_C as ecTotalMoneyC, ce.contract_available_money as contractAvailableMoney, ce.estimate_available_money as estimateAvailableMoney from Con_EC ce inner join multi_contract_con_ec mcce on mcce.uuid = ce.multi_contract_con_ec_id where ce.Ec_Change_Type = '01' and mcce.state = #{finishedState} and mcce.project_id = #{projectId} and ce.Con_Id = #{contractId} union all select ce.Ec_Id as ecId, ce.Con_Id as conId, sv.Svis_Id as flowId, null as changeCode, '02' as ecChangeType, ce.Ec_Apply_Money as ecApplyMoney, ce.Ec_Apply_Money_Type as ecApplyMoneyType, sv.Svis_State as ecState, sv.Svis_State_Time as ecStateTime, ce.Ec_Total_Money_C as ecTotalMoneyC, ce.contract_available_money as contractAvailableMoney, ce.estimate_available_money as estimateAvailableMoney from Con_EC ce inner join Con_Svis sv on sv.Svis_Id = ce.Con_Svis_Id where ce.Ec_Change_Type = '02' and sv.Svis_State = #{finishedState} and sv.P_Id = #{projectId} and ce.Con_Id = #{contractId} ) history inner join Con_Contract cc on cc.Con_Id = history.conId inner join Pre_Project mn on mn.P_Id = cc.Con_Project_Id ${authSql} and mn.P_Id = #{projectId}
and history.ecId <> #{excludeEcId}
order by case when history.ecStateTime is null then 1 else 0 end, history.ecStateTime desc, history.ecId desc

select
sum(case when ce.ec_apply_money_type = 0 then -ce.ec_apply_money else ce.ec_apply_money end)
from con_ec ce
left join con_contract cc on cc.con_id = ce.con_id
where 1 = 1
and cc.con_project_id = #{projectId}
and ce.ec_state = 7

    and ce.con_id = #{contractId}


    and ce.ec_change_type = #{ecChangeType}

select mn.Con_Id, ifnull(sum(mn.Ec_Apply_Money), 0) as ecApplyMoney from Con_EC mn left join engineering_reporting er on er.er_id = mn.er_id where er.er_state = 7 and mn.Ec_Id not in (select ekr.Ec_Id from engineering_keep_record ekr where ekr.State = 7
and ekr.Con_Id in
#{conId}
)
and mn.Con_Id in
#{conId}
group by mn.Con_Id

select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Party_B_Id as conPartyBId, con.Con_Project_Id as pId, c1.C_Name as ecSupervisorName, c2.C_Name as ecConsultingUnitName, d1.D_Name as ecDepName, c5.C_Name as ecCreateCName, c6.C_Name as conPartyBName, c7.C_Name as ecDesignName, c8.C_Name as ecPutForwardName, c9.C_Name as ecConstName, c10.C_Name as ecCostConsulName, c1.C_Abbreviation as ecSupervisorAbbName, c2.C_Abbreviation as ecConsultingUnitAbbName, c5.C_Abbreviation as ecCreateCAbbName, c6.C_Abbreviation as conPartyBAbbName, c7.C_Abbreviation as ecDesignAbbName, cl.Cl_Title as clTitle, sec.Sec_Name as secName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Major as dcoMajor, enis.Enis_Code as enisCode, ces.Enis_Project_Name as enisName, ces.Enis_Code as enisCodeSelf, pro1.P_Id as projectId, pro1.P_Name as projectName, pro1.P_Code as projectCode, pec.Ec_Name as preEcName, pec.Ec_Code as preEcCode, con.con_declare_money conDeclareMoney, mn.* from Con_EC mn left join Pre_Project pro1 on mn.P_ID=pro1.P_ID left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Ec_Supervisor_Id=c1.C_Id left join SYS_Company c2 on mn.Ec_Consulting_Unit_Id=c2.C_Id left join Con_Contact_List cl on cl.Cl_Id=mn.Cl_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID
left join SYS_Department d1 on mn.Ec_Dep=d1.D_Id left join SYS_Company c5 on mn.Ec_Create_C_Id=c5.C_Id left join SYS_Company c6 on con.Con_Party_B_Id=c6.C_Id left join SYS_Company c7 on mn.Ec_Design_Id=c7.C_Id left join SYS_Company c8 on mn.Ec_Put_Forward=c8.C_Id left join SYS_Company c9 on mn.Ec_Construction=c9.C_Id left join SYS_Company c10 on mn.Ec_Cost_Consulting=c10.C_Id left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id left join Con_Enis enis on dco.Enis_Id=enis.Enis_Id left join Con_Enis ces on ces.Enis_Id=mn.Enis_Id left join Con_EC pec on pec.Ec_Id=mn.Pre_Ec_Id
mn.Ec_State!=3
and mn.Te_Id = #{teId}
and mn.Ec_Change_Type=#{params.ecChangeType}
and mn.Ec_Apply_Money_Type=#{params.ecApplyMoneyType}
and mn.Ec_Duration_Type=#{params.ecDurationType}
and mn.Ec_Design_Order=#{params.ecDesignOrder}
and mn.Ec_Audit_Type=#{params.ecAuditType}
and pro.P_ID=#{params.pId}
and mn.Ec_State=#{params.ecState}
and mn.Ec_Type=#{params.ecType}
and mn.Ec_Dep=#{params.ecDep}
and mn.Ec_Main_Cause=#{params.ecMainCause}
and mn.Ec_Drawing_Library=#{params.ecDrawingLibrary}
and mn.Ec_Construction_Name like concat('%',#{params.ecConstructionName},'%')
and mn.Ec_Name like concat('%',#{params.ecName},'%')
and mn.Ec_Part_Name like concat('%',#{params.ecPartName},'%')
and mn.Ec_Code like concat('%',#{params.ecCode},'%')
and mn.Ec_Responsible_Party like concat('%',#{params.ecResponsibleParty},'%')
and mn.Ec_Grade like concat('%',#{params.ecGrade},'%')
and mn.Ec_Warn like concat('%',#{params.ecWarn},'%')
and mn.Ec_Design_Order_Code like concat('%',#{params.ecDesignOrderCode},'%')
and mn.Ec_Create_Uname like concat('%',#{params.ecCreateUname},'%')
and likeCname(#{params.ecConstName},c9.C_Id)=true
and likeCname(#{params.ecCostConsulName},c10.C_Id)=true
and likeCname(#{params.ecSupervisorName},c1.C_Id)=true
and likePname(#{params.pName},pro.P_Id)=true
and likeCname(#{params.pConstructionUnitName},proc.C_Id)=true
and c9.C_Name like concat('%',#{params.ecConstName},'%')
and c10.C_Name like concat('%',#{params.ecCostConsulName},'%')
and c1.C_Name like concat('%',#{params.ecSupervisorName},'%')
and pro.P_Name like concat('%',#{params.pName},'%')
and proc.C_Name like concat('%',#{params.pConstructionUnitName},'%')
and mn.Ec_Reason like concat('%',#{params.ecReason},'%')
and mn.Ec_Content like concat('%',#{params.ecContent},'%')
and enis.Enis_Code like concat('%',#{params.enisCode},'%')
and mn.Con_Id= #{params.conId}
and con.Con_Name like concat('%',#{params.conName},'%')
and d1.D_Name like concat('%',#{params.ecDepName},'%')
and ces.Enis_Project_Name like concat('%',#{params.enisName},'%')
and mn.Ec_Id in (select Ec_Id from Con_EC_Fee where Ecf_State!=3)
and mn.Ec_Id not in (select Ec_Id from Con_EC_Fee where Ecf_State!=3 and Ec_Id is not null)
and mn.ec_Data_Separate = #{params.ecDataSeparate}
and mn.multi_contract_con_ec_id = #{params.multiContractConEcId}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ec_Create_Time desc
